  "inlineSchema": "// ResolveX Autonomous Customer Resolution Agent — MongoDB Atlas Production Schema\n// Datasource provider set to MongoDB with URL read from environment variable MONGODB_URI\n\ndatasource db {\n  provider = \"mongodb\"\n  url      = env(\"MONGODB_URI\")\n}\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  output        = \"../src/db/generated/client-mongodb\"\n  binaryTargets = [\"native\"]\n}\n\nmodel Customer {\n  id        String   @id @map(\"_id\")\n  tenantId  String   @default(\"tenant-a\")\n  name      String\n  email     String   @unique\n  tier      String   @default(\"STANDARD\")\n  riskScore Float    @default(0.0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  orders        Order[]\n  tickets       Ticket[]\n  coupons       Coupon[]\n  notifications Notification[]\n}\n\nmodel Product {\n  id                  String   @id @map(\"_id\")\n  name                String\n  category            String\n  price               Float\n  stockQuantity       Int      @default(0)\n  replacementEligible Boolean  @default(true)\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  orderItems OrderItem[]\n}\n\nmodel Order {\n  id             String    @id @map(\"_id\")\n  tenantId       String    @default(\"tenant-a\")\n  customerId     String\n  customer       Customer  @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  status         String    @default(\"PROCESSING\")\n  totalAmount    Float\n  currency       String    @default(\"INR\")\n  deliveryDate   DateTime?\n  shippingStatus String    @default(\"PENDING\")\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  items   OrderItem[]\n  tickets Ticket[]\n  refunds RefundTransaction[]\n}\n\nmodel OrderItem {\n  id        String  @id @map(\"_id\")\n  orderId   String\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n  quantity  Int\n  unitPrice Float\n}\n\nmodel Ticket {\n  id                String    @id @map(\"_id\")\n  tenantId          String    @default(\"tenant-a\")\n  customerId        String\n  customer          Customer  @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  orderId           String?\n  order             Order?    @relation(fields: [orderId], references: [id])\n  issueType         String\n  customerMessage   String\n  status            String    @default(\"OPEN\")\n  resolutionSummary String?\n  refundAmount      Float?\n  replacementSku    String?\n  requiresApproval  Boolean   @default(false)\n  requiresConsent   Boolean   @default(false)\n  approvalStatus    String?\n  consentStatus     String?\n  approvalToken     String?\n  idempotencyKey    String?   @unique\n  resolvedAt        DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  agentRuns   AgentRun[]\n  traces      AgentTrace[]\n  caseRecords CaseRecord[]\n}\n\nmodel PolicyVersion {\n  id          String   @id @map(\"_id\")\n  tenantId    String   @default(\"tenant-a\")\n  policyId    String\n  version     Int      @default(1)\n  rulesJson   String\n  isActive    Boolean  @default(true)\n  createdById String   @default(\"sys-admin\")\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@unique([policyId, version])\n}\n\nmodel AgentRun {\n  id             String   @id @map(\"_id\")\n  tenantId       String   @default(\"tenant-a\")\n  ticketId       String\n  ticket         Ticket   @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  status         String   @default(\"PENDING\")\n  intent         String?\n  confidence     Float?\n  executedTools  String?\n  overallOutcome String?\n  idempotencyKey String?  @unique\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  traces AgentTrace[]\n}\n\nmodel AgentTrace {\n  id              String   @id @map(\"_id\")\n  agentRunId      String\n  agentRun        AgentRun @relation(fields: [agentRunId], references: [id], onDelete: Cascade)\n  ticketId        String?\n  ticket          Ticket?  @relation(fields: [ticketId], references: [id])\n  step            String\n  evidenceDetails String\n  actor           String   @default(\"SYSTEM\")\n  timestamp       DateTime @default(now())\n}\n\nmodel CaseRecord {\n  id                     String   @id @map(\"_id\")\n  tenantId               String   @default(\"tenant-a\")\n  ticketId               String\n  ticket                 Ticket   @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  orderId                String?\n  customerId             String\n  issueType              String\n  customerMessage        String\n  status                 String   @default(\"OPEN\")\n  resolutionSummary      String?\n  requiresCustomerAction Boolean  @default(false)\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n}\n\nmodel RefundTransaction {\n  id             String   @id @map(\"_id\")\n  tenantId       String   @default(\"tenant-a\")\n  orderId        String\n  order          Order    @relation(fields: [orderId], references: [id])\n  amount         Float\n  currency       String   @default(\"INR\")\n  status         String   @default(\"SUCCESS\")\n  idempotencyKey String   @unique\n  createdAt      DateTime @default(now())\n}\n\nmodel Coupon {\n  id         String    @id @map(\"_id\")\n  tenantId   String    @default(\"tenant-a\")\n  customerId String\n  customer   Customer  @relation(fields: [customerId], references: [id])\n  code       String    @unique\n  discount   Float\n  isRedeemed Boolean   @default(false)\n  expiresAt  DateTime?\n  createdAt  DateTime  @default(now())\n}\n\nmodel Notification {\n  id             String   @id @map(\"_id\")\n  tenantId       String   @default(\"tenant-a\")\n  customerId     String\n  customer       Customer @relation(fields: [customerId], references: [id])\n  type           String\n  message        String\n  channel        String   @default(\"EMAIL\")\n  status         String   @default(\"SENT\")\n  idempotencyKey String   @unique\n  createdAt      DateTime @default(now())\n}\n\nmodel ExecutionJob {\n  id              String    @id @map(\"_id\")\n  tenantId        String    @default(\"tenant-a\")\n  runId           String    @unique\n  status          String    @default(\"QUEUED\")\n  payloadJson     String\n  attemptCount    Int       @default(0)\n  maxAttempts     Int       @default(3)\n  lastError       String?\n  workerId        String?\n  leaseGeneration Int       @default(0)\n  leaseExpiresAt  DateTime?\n  idempotencyKey  String    @unique\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n}\n\nmodel MetricSnapshot {\n  id         String   @id @map(\"_id\")\n  tenantId   String   @default(\"tenant-a\")\n  metricName String\n  value      Float\n  labelsJson String\n  timestamp  DateTime @default(now())\n}\n\nmodel AuditLog {\n  id            String   @id @map(\"_id\")\n  tenantId      String   @default(\"tenant-a\")\n  correlationId String\n  action        String\n  actor         String\n  detailsJson   String\n  timestamp     DateTime @default(now())\n}\n",
